<?php
declare(strict_types=1);
namespace Nerozon\Questionnaire;
final readonly class QuestionnaireAnswer{public function __construct(public string $questionId,public string $type,public string|array $value){}public function toArray():array{return ['question_id'=>$this->questionId,'type'=>$this->type,'value'=>$this->value];}}
final readonly class QuestionnaireSubmission{public function __construct(public string $submissionId,public string $questionnaireId,public string $questionnaireVersion,public int $schemaVersion,public \DateTimeImmutable $submittedAt,public array $answers){}public function toArray():array{return ['submission_id'=>$this->submissionId,'questionnaire_id'=>$this->questionnaireId,'questionnaire_version'=>$this->questionnaireVersion,'schema_version'=>$this->schemaVersion,'submitted_at'=>$this->submittedAt->format('Y-m-d\\TH:i:s.u\\Z'),'answers'=>array_map(fn(QuestionnaireAnswer $a)=>$a->toArray(),$this->answers)];}}
final class QuestionnaireDefinition{public const ID='S092026',VERSION='20260830',SCHEMA_VERSION=1;private const TYPES=[1=>'single_choice',2=>'multi_choice',3=>'single_choice',4=>'single_choice',5=>'scale',6=>'multi_choice',7=>'single_choice',8=>'scale',9=>'scale',10=>'short_text',11=>'scale',12=>'scale',13=>'scale',14=>'scale',15=>'single_choice',16=>'multi_choice',17=>'short_text',18=>'single_choice',19=>'single_choice',20=>'short_text'];private const COUNTS=[1=>4,2=>8,3=>4,4=>4,5=>5,6=>9,7=>4,8=>5,9=>5,11=>5,12=>5,13=>5,14=>5,15=>4,16=>7,18=>4,19=>8];public static function normalizeAnswers(array $raw):array{$seen=[];$out=[];foreach($raw as $i=>$item){if(!is_array($item)||array_diff(array_keys($item),['question_id','type','value'])||!array_key_exists('question_id',$item)||!array_key_exists('type',$item)||!array_key_exists('value',$item))throw new InvalidQuestionnaireSubmission("Invalid answer at index $i");$qid=$item['question_id'];$type=$item['type'];if(!is_string($qid)||!preg_match('/^S092026Q(0[1-9]|1[0-9]|20)$/',$qid,$m))throw new InvalidQuestionnaireSubmission('Unknown question_id');$n=(int)$m[1];if(isset($seen[$qid]))throw new InvalidQuestionnaireSubmission('Duplicate question_id');$seen[$qid]=true;$expected=self::TYPES[$n]??null;if($type!==$expected)throw new InvalidQuestionnaireSubmission('Invalid answer type');$v=$item['value'];if($expected==='short_text'){if(!is_string($v))throw new InvalidQuestionnaireSubmission('short_text must be string');$v=trim($v);if($v==='')continue;if(self::charLength($v)>4000)throw new InvalidQuestionnaireSubmission('short_text too long');}elseif($expected==='multi_choice'){if(!is_array($v))throw new InvalidQuestionnaireSubmission('multi_choice must be array');$v=array_values($v);if($v===[])continue;if(count($v)!==count(array_unique($v,SORT_STRING)))throw new InvalidQuestionnaireSubmission('Duplicate choice');foreach($v as $choice)self::assertChoice($qid,$choice,self::COUNTS[$n]);}else self::assertChoice($qid,$v,self::COUNTS[$n]);$out[]=new QuestionnaireAnswer($qid,$expected,$v);}return $out;}private static function charLength(string $v):int{$c=preg_match_all('/./us',$v,$m);if($c===false)throw new InvalidQuestionnaireSubmission('short_text invalid UTF-8');return $c;}private static function assertChoice(string $qid,mixed $choice,int $count):void{if(!is_string($choice)||!preg_match('/^'.preg_quote($qid,'/').'A(\\d{2})$/',$choice,$m))throw new InvalidQuestionnaireSubmission('Invalid answer_id');$n=(int)$m[1];if($n<1||$n>$count)throw new InvalidQuestionnaireSubmission('Unknown answer_id');}}
